"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useMounted } from "../lib/hooks";

export interface CountdownProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Moment waarnaar afgeteld wordt. */
  to: Date | string | number;
  /** Toont dagen zolang er meer dan 24 uur over is. */
  showDays?: boolean;
  /** Alleen de cijfers, gescheiden door dubbele punten. */
  compact?: boolean;
  /** Wordt één keer aangeroepen zodra de teller op nul staat. */
  onComplete?: () => void;
  labels?: { days: string; hours: string; minutes: string; seconds: string };
  /**
   * `plain` toont kale cijfers, `cards` zet elk deel in een tegel met een
   * klapanimatie. In beide varianten rolt elk gewijzigd cijfer binnen.
   */
  variant?: "plain" | "cards";
}

const STANDAARD = { days: "dagen", hours: "uur", minutes: "min", seconds: "sec" };

function resterend(doel: number) {
  const verschil = Math.max(doel - Date.now(), 0);
  return {
    d: Math.floor(verschil / 86400000),
    u: Math.floor((verschil / 3600000) % 24),
    m: Math.floor((verschil / 60000) % 60),
    s: Math.floor((verschil / 1000) % 60),
    klaar: verschil === 0,
  };
}

/** Countdown — telt af naar een moment en stopt vanzelf op nul. */
export const Countdown = React.forwardRef<HTMLDivElement, CountdownProps>(function Countdown(
  { to, showDays = true, compact, onComplete, labels = STANDAARD, variant = "plain", className, ...rest },
  ref
) {
  const doel = React.useMemo(() => new Date(to).getTime(), [to]);
  // De server weet niet hoe laat het in de browser is. Tot de eerste render in
  // de browser voorbij is tonen we streepjes; anders verschilt de HTML van de
  // server van die van de client en klaagt React over hydratie.
  const gemonteerd = useMounted();
  const [tijd, setTijd] = React.useState(() => resterend(doel));
  const gemeld = React.useRef(false);

  React.useEffect(() => {
    gemeld.current = false;
    setTijd(resterend(doel));
    const timer = window.setInterval(() => {
      const volgende = resterend(doel);
      setTijd(volgende);
      if (volgende.klaar && !gemeld.current) {
        gemeld.current = true;
        onComplete?.();
        window.clearInterval(timer);
      }
    }, 1000);
    return () => window.clearInterval(timer);
  }, [doel, onComplete]);

  const delen = [
    ...(showDays && (!gemonteerd || tijd.d > 0) ? [{ waarde: tijd.d, label: labels.days }] : []),
    { waarde: tijd.u, label: labels.hours },
    { waarde: tijd.m, label: labels.minutes },
    { waarde: tijd.s, label: labels.seconds },
  ];

  return (
    <div
      ref={ref}
      role="timer"
      data-done={gemonteerd && tijd.klaar ? "" : undefined}
      data-variant={variant}
      className={cn("lui-countdown", compact && "lui-countdown-compact", className)}
      {...rest}
    >
      {delen.map((deel, index) => (
        <React.Fragment key={deel.label}>
          {compact && index > 0 && <span className="lui-countdown-dubbelepunt">:</span>}
          <span className="lui-countdown-deel">
            <span className="lui-countdown-getal">
              {(gemonteerd ? String(deel.waarde).padStart(2, "0") : "--").split("").map((teken, positie, alle) => (
                // De key verandert mee met het cijfer, zodat alleen gewijzigde
                // cijfers opnieuw monteren en hun animatie afspelen.
                <span key={`${alle.length - positie}-${teken}`} className="lui-countdown-cijfer">
                  {teken}
                </span>
              ))}
            </span>
            {!compact && <span className="lui-countdown-label">{deel.label}</span>}
          </span>
        </React.Fragment>
      ))}
    </div>
  );
});

/* ============================ Countdown ============================ */
.lui-countdown { display: inline-flex; align-items: flex-end; gap: 12px; }

.lui-countdown-deel { display: inline-flex; flex-direction: column; align-items: center; gap: 4px; }
.lui-countdown-getal {
  font-family: var(--mono); font-size: 26px; font-weight: 700; line-height: 1;
  color: var(--text); font-variant-numeric: tabular-nums;
}
.lui-countdown-label {
  font-size: 10.5px; font-weight: 650; letter-spacing: .06em;
  text-transform: uppercase; color: var(--text-3);
}

.lui-countdown-compact { gap: 3px; align-items: center; }
.lui-countdown-compact .lui-countdown-getal { font-size: 20px; }
.lui-countdown-dubbelepunt { font-family: var(--mono); font-size: 20px; color: var(--text-3); }

.lui-countdown[data-done] .lui-countdown-getal { color: var(--text-3); }

/* ---------- Cijfers rollen binnen ---------- */
.lui-countdown-getal { display: inline-flex; overflow: hidden; padding-block: 2px; }
.lui-countdown-cijfer { display: inline-block; animation: lui-countdown-roll .42s var(--ease-pop) both; }
@keyframes lui-countdown-roll {
  from { transform: translateY(-70%); opacity: 0; filter: blur(2px); }
  to { transform: none; opacity: 1; filter: none; }
}
.lui-countdown-compact .lui-countdown-dubbelepunt { animation: lui-countdown-blink 1s steps(1) infinite; }
@keyframes lui-countdown-blink { 50% { opacity: .35; } }
.lui-countdown[data-done] .lui-countdown-dubbelepunt { animation: none; }
.lui-countdown[data-done] .lui-countdown-deel { animation: lui-pop .5s var(--ease-pop) both; }

/* ---------- Variant: tegels die klappen ---------- */
.lui-countdown[data-variant="cards"] { gap: 10px; }
.lui-countdown[data-variant="cards"] .lui-countdown-getal {
  position: relative; padding: 10px 10px; min-width: 2.6ch; justify-content: center;
  border-radius: var(--r-md); background: var(--surface-2); border: 1px solid var(--border);
  box-shadow: var(--sh-sm), inset 0 -1px 0 rgb(0 0 0 / .04);
  font-size: 30px; perspective: 300px;
}
.lui-countdown[data-variant="cards"] .lui-countdown-getal::after {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 1px;
  background: color-mix(in srgb, var(--border) 80%, transparent);
}
.lui-countdown[data-variant="cards"] .lui-countdown-cijfer {
  transform-origin: 50% 55%; backface-visibility: hidden;
  animation: lui-countdown-flip .5s var(--ease-out) both;
}
@keyframes lui-countdown-flip {
  from { transform: rotateX(-95deg); opacity: .2; }
  60% { transform: rotateX(12deg); opacity: 1; }
  to { transform: none; opacity: 1; }
}
.lui-countdown[data-variant="cards"].lui-countdown-compact .lui-countdown-getal { font-size: 22px; padding: 7px 8px; }
